using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sets the value of an option. (Check the list of available options on https://core.telegram.org/tdlib/options.) Only writable options can be set. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetOptionAsync(string name = default, OptionValue value = default)
    {

           using var activity =  StartCallActivity("SetOptionAsync", typeof(SetOption).FullName ?? "SetOptionAsync");

           try
           {
             return client.SetOptionAsync(name, value);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd